import zlib, struct, lzma

def enc_num(n):
    if n < 0x80:
        return bytes([n])
    elif n < 0x4000:
        return bytes([0x80 | (n >> 8), n & 0xFF])
    elif n < 0x200000:
        return bytes([0xC0 | (n >> 16), (n >> 8) & 0xFF, n & 0xFF])
    elif n < 0x10000000:
        return bytes([0xE0 | (n >> 24), (n >> 16) & 0xFF, (n >> 8) & 0xFF, n & 0xFF])
    else:
        return bytes([0xFF]) + struct.pack("<Q", n)

def create_7z_archive(filename, files_list):
    """
    files_list: list of (rel_path, content_bytes, is_dir)
    """
    # Separate files and directories
    data_bytes = b""
    files_info = []

    for rel_path, content, is_dir in files_list:
        if is_dir:
            files_info.append({"name": rel_path, "size": 0, "crc": 0, "is_dir": True})
        else:
            crc = zlib.crc32(content) & 0xFFFFFFFF
            files_info.append({"name": rel_path, "size": len(content), "crc": crc, "is_dir": False})
            data_bytes += content

    # Compress data stream with LZMA2
    if data_bytes:
        compressor = lzma.LZMACompressor(format=lzma.FORMAT_RAW, filters=[{"id": lzma.FILTER_LZMA2, "dict_size": 1 << 20}])
        comp_stream = compressor.compress(data_bytes) + compressor.flush()
    else:
        comp_stream = b""

    pack_info = b"\x06\x00\x01\x09" + enc_num(len(comp_stream)) + b"\x00" if comp_stream else b""

    non_dir_files = [f for f in files_info if not f["is_dir"]]

    if data_bytes:
        unpack_info = b"\x07\x0b\x01\x00\x01\x21\x21\x01\x14" + enc_num(len(data_bytes)) + b"\x00"
        if len(non_dir_files) > 1:
            sub_streams = b"\x08\x0d" + enc_num(len(non_dir_files)) + b"\x09"
            for f in non_dir_files[:-1]:
                sub_streams += enc_num(f["size"])
            sub_streams += b"\x0a\x01"
            for f in non_dir_files:
                sub_streams += struct.pack("<I", f["crc"])
            sub_streams += b"\x00"
        else:
            sub_streams = b"\x08\x0a\x01" + struct.pack("<I", non_dir_files[0]["crc"]) + b"\x00"
        main_streams = b"\x04" + pack_info + unpack_info + sub_streams + b"\x00"
    else:
        main_streams = b""

    # FilesInfo (0x05)
    fi = b"\x05" + enc_num(len(files_info))

    # Empty stream / Empty file
    has_empty = any(f["is_dir"] or f["size"] == 0 for f in files_info)
    if has_empty:
        empty_stream_bits = []
        empty_file_bits = []
        for f in files_info:
            is_empty = 1 if (f["is_dir"] or f["size"] == 0) else 0
            empty_stream_bits.append(is_empty)
            if is_empty:
                empty_file_bits.append(1 if f["is_dir"] else 0)

        def pack_bits(bits):
            res = bytearray()
            curr = 0
            count = 0
            for b in bits:
                if b:
                    curr |= (1 << count)
                count += 1
                if count == 8:
                    res.append(curr)
                    curr = 0
                    count = 0
            if count > 0:
                res.append(curr)
            return bytes(res)

        fi += b"\x0e" + enc_num(len(empty_stream_bits)) + pack_bits(empty_stream_bits)
        if any(b == 1 for b in empty_file_bits):
            fi += b"\x0f" + enc_num(len(empty_file_bits)) + pack_bits(empty_file_bits)

    # Names
    utf16_names = b"\x00" # external = 0
    for f in files_info:
        utf16_names += f["name"].encode("utf-16le") + b"\x00\x00"
    fi += b"\x11" + enc_num(len(utf16_names)) + utf16_names

    # Attributes
    attr_data = b"\x01\x00" # all defined = 1, external = 0
    for f in files_info:
        attr = 0x10 if f["is_dir"] else 0x20
        attr_data += struct.pack("<I", attr)
    fi += b"\x15" + enc_num(len(attr_data)) + attr_data + b"\x00"

    header = b"\x01" + main_streams + fi + b"\x00"

    next_ofs = len(comp_stream)
    next_sz = len(header)
    next_crc = zlib.crc32(header) & 0xFFFFFFFF

    start_hdr_data = struct.pack("<QQI", next_ofs, next_sz, next_crc)
    start_hdr_crc = zlib.crc32(start_hdr_data) & 0xFFFFFFFF

    sig = b"7z\xbc\xaf\x27\x1c\x00\x04"
    start_hdr = sig + struct.pack("<I", start_hdr_crc) + start_hdr_data

    with open(filename, "wb") as f:
        f.write(start_hdr)
        f.write(comp_stream)
        f.write(header)

